let mix = require('laravel-mix');

let defaultSassOptions = {
    sassOptions: {
        outputStyle: "compressed",
    }
};

mix
    .sourceMaps()

    .version()

    .options({
        processCssUrls: false,
    })

    /**
     * Configurazione sottostante di webpack.
     * Uso mode 'development' per compilare solo il file che viene di volta in volta modificato e non l'intero set.
     */
    .webpackConfig({
        mode: 'development',
        optimization : {
            // per js, forza minificazione in seguito a uso della modalità 'development' che non lo farebbe di default
            minimize : true
        },
        devtool: 'source-map' // in collaborazione con sourceMaps() - v. https://github.com/laravel-mix/laravel-mix/issues/1793
    })


    // script di boot
    .js('resources/js/boot.js', 'public/js/build/boot.js')

    // js vendor
    .js('resources/js/vendor.js',  'public/js/build/vendor.js')

    // app.js
    .js('resources/js/app.js', 'public/js/build/app.js')

    // css
    .sass('resources/sass/boot.scss', 'public/css/build/boot.css', {
    })
    .sass('resources/sass/main.scss', 'public/css/build/main.css', defaultSassOptions)
    .sass('resources/sass/pages.scss', 'public/css/build/pages.css', defaultSassOptions)

    // css pannello
    .sass('resources/vendor/marvin/sass/main.scss', 'public/admin/css/main.css', defaultSassOptions)


mix.browserSync({
    port : process.env.MIX_BROWSERSYNC_PORT,
    proxy : process.env.MIX_BROWSERSYNC_PROXY,
    open : false, // perchè in container docker
    injectChanges: false,
    files : ["public/css/build/*", "public/js/build/*", "resources/views/**"],
});

